import React, { useState, useEffect } from 'react';
import axiosInstance from 'axios';

export default function TeacherQuiz({ userName, subject, qualifications, teacherGrades, timetable }) {
  const [quizzes, setQuizzes] = useState(() => {
    const savedQuizzes = localStorage.getItem('aura_math_quizzes');
    return savedQuizzes ? JSON.parse(savedQuizzes) : [];
  });

  const [masterBank, setMasterBank] = useState(() => {
    const savedBank = localStorage.getItem('aura_math_quiz_bank');
    return savedBank ? JSON.parse(savedBank) : [];
  });

  const [selectedQuizId, setSelectedQuizId] = useState('');
  const [quizTitle, setQuizTitle] = useState('');

  // Relational Tables Local States
  const [dbSubjects, setDbSubjects] = useState([]);
  const [dbTimetable, setDbTimetable] = useState([]);
  const [activeSubject, setActiveSubject] = useState('');

  // Form States for Questions
  const [editingId, setEditingId] = useState(null);
  const [qText, setQText] = useState('');
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');
  const [correctOpt, setCorrectOpt] = useState('A');
  const [qMarks, setQMarks] = useState(2);

  // 🟢 FIXED URL & ENDPOINTS FOR PORT 8082
  const refreshData = () => {
    axiosInstance.get('http://localhost:8082/api/quizzes')
      .then(res => setQuizzes(Array.isArray(res.data) ? res.data : []))
      .catch(err => console.log("Quizzes Fetch Error:", err));
    
    axiosInstance.get('http://localhost:8082/api/question-bank')
      .then(res => setMasterBank(Array.isArray(res.data) ? res.data : []))
      .catch(err => console.log("Question Bank Fetch Error:", err));

    axiosInstance.get('http://localhost:8082/api/view-subjects')
      .then(res => {
        const subs = Array.isArray(res.data) ? res.data : [];
        setDbSubjects(subs);
        if (subs.length > 0 && !activeSubject) {
          setActiveSubject(subs[0].subject_name);
        }
      }).catch(() => {});

    axiosInstance.get('http://localhost:8082/api/timetable')
      .then(res => setDbTimetable(Array.isArray(res.data) ? res.data : []))
      .catch(() => {});
  };

  useEffect(() => { 
    refreshData(); 
  }, []);

  // 🟢 FIXED FILTER LOGIC: server.js එකෙන් එන සැබෑ 'teacher' සහ 'subject' නමෙන් කෙලින්ම ෆිල්ටර් කිරීම
  const myTimeSlots = dbTimetable.filter(t => t.teacher === userName);
  const myUniqueSubjects = [...new Set(myTimeSlots.map(t => t.subject))];
  const availableGrades = [...new Set(myTimeSlots.filter(t => t.subject === (activeSubject || 'Mathematics')).map(t => t.grade))];

  const [formPaperGrade, setFormPaperGrade] = useState('Grade 8');

  // ශ්‍රේණි මතකයට ලෝඩ් වූ විගස ඩිෆෝල්ට් අගය පළමු ශ්‍රේණියට (Grade 6) සින්ක් කිරීම
  useEffect(() => {
    if (availableGrades.length > 0) {
      setFormPaperGrade(availableGrades[0]);
    }
  }, [dbTimetable, activeSubject]);

  useEffect(() => {
    if (myUniqueSubjects.length > 0 && !activeSubject) {
      setActiveSubject(myUniqueSubjects[0]);
    }
  }, [dbTimetable]);

  const saveQuizzesToStorage = (newQuizzes) => { setQuizzes(newQuizzes); localStorage.setItem('aura_math_quizzes', JSON.stringify(newQuizzes)); };
  const saveBankToStorage = (newBank) => { setMasterBank(newBank); localStorage.setItem('aura_math_quiz_bank', JSON.stringify(newBank)); };

  const handleCreatePaper = (e) => {
    e.preventDefault();
    const payload = { title: quizTitle, grade: formPaperGrade, subject: activeSubject || 'Mathematics', teacher_name: userName, is_enabled: 0 };
    axiosInstance.post('http://localhost:8082/api/add-quiz', payload).then(() => refreshData()).catch(() => {
        const newQuiz = { id: Date.now(), title: quizTitle, grade: formPaperGrade, subject_name: activeSubject || 'Mathematics', teacher_name: userName, is_enabled: false };
        saveQuizzesToStorage([...quizzes, newQuiz]); setSelectedQuizId(newQuiz.id.toString()); setQuizTitle('');
    });
  };

  const handleToggleEnable = (quiz) => {
    const updatedStatus = quiz.is_enabled === 1 || quiz.is_enabled === true ? 0 : 1;
    axiosInstance.put(`http://localhost:8082/api/toggle-quiz/${quiz.id}`, { ...quiz, is_enabled: updatedStatus }).then(() => refreshData()).catch(() => {
        const updated = quizzes.map(qz => qz.id === quiz.id ? { ...qz, is_enabled: !isEnabled(qz) } : qz); saveQuizzesToStorage(updated);
    });
  };

  const isEnabled = (quiz) => quiz.is_enabled === 1 || quiz.is_enabled === true;

  const handleSaveQuestion = (e) => {
    e.preventDefault();
    const payload = { quiz_id: selectedQuizId ? parseInt(selectedQuizId) : 0, question_text: qText, marks: qMarks, option_a: optA, option_b: optB, option_c: optC, option_d: optD, correct_option: correctOpt };
    if (editingId) {
      axiosInstance.put(`http://localhost:8082/api/edit-question/${editingId}`, payload).then(() => { setEditingId(null); clearForm(); refreshData(); }).catch(() => {
          const updated = masterBank.map(q => q.id === editingId ? { ...q, ...payload } : q); saveBankToStorage(updated); setEditingId(null); clearForm();
      });
    } else {
      axiosInstance.post('http://localhost:8082/api/add-question', payload).then(() => { clearForm(); refreshData(); }).catch(() => {
          saveBankToStorage([{ id: Date.now(), ...payload }, ...masterBank]); clearForm();
      });
    }
  };

  const handleQuickLink = (question) => {
    if (!selectedQuizId) { alert("⚠️ Choose target paper first!"); return; }
    const updated = masterBank.map(q => q.id === question.id ? { ...q, quiz_id: parseInt(selectedQuizId) } : q);
    saveBankToStorage(updated); alert("➕ Linked!");
  };

  const handleDeleteQuestion = (id) => { if (window.confirm("Delete?")) { saveBankToStorage(masterBank.filter(q => q.id !== id)); } };
  const handleUnlinkQuestion = (question) => { saveBankToStorage(masterBank.map(q => q.id === question.id ? { ...q, quiz_id: 0 } : q)); };
  const clearForm = () => { setQText(''); setOptA(''); setOptB(''); setOptC(''); setOptD(''); setCorrectOpt('A'); };
  const handleStartEdit = (q) => { setEditingId(q.id); setQText(q.question_text); setOptA(q.option_a); setOptB(q.option_b); setOptC(q.option_c); setOptD(q.option_d); setCorrectOpt(q.correct_option); setQMarks(q.marks); };

  const filteredQuizzes = quizzes.filter(q => q.subject_name === (activeSubject || 'Mathematics'));
  const activePaperQuestions = masterBank.filter(q => q.quiz_id === parseInt(selectedQuizId));
  const activeQuizDetails = quizzes.find(qz => qz.id === parseInt(selectedQuizId));

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '25px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f8fafc', padding: '12px 20px', borderRadius: '12px', border: '1px solid #cbd5e1' }}>
        <div><h2 style={{ color: '#1e293b', margin: 0, fontSize: '18px' }}>📝 MCQ Exam Dashboard Management</h2></div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{ fontSize: '13px', fontWeight: 'bold', color: '#475569' }}>Active Subject:</span>
          <select value={activeSubject} onChange={e => { setActiveSubject(e.target.value); setSelectedQuizId(''); }} style={{ padding: '8px 14px', borderRadius: '8px', border: '1px solid #cbd5e1', fontWeight: 'bold', fontSize: '13px', outline: 'none' }}>
            {myUniqueSubjects.map(subName => <option key={subName} value={subName}>{subName}</option>)}
            {myUniqueSubjects.length === 0 && <option value="Mathematics">Mathematics</option>}
          </select>
        </div>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
        <div style={styles.card('#15803d')}>
          <h4 style={styles.stepTitle('#15803d')}>Step 1: Create a New Quiz Paper</h4>
          <form onSubmit={handleCreatePaper} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <input type="text" placeholder="e.g., 2 වාර මැද ඇගයීම" value={quizTitle} onChange={e => setQuizTitle(e.target.value)} required style={styles.fullInput} />
            
            {/* 🟢 FIXED DROPDOWN OPTIONS LIST */}
            <select value={formPaperGrade} onChange={e => setFormPaperGrade(e.target.value)} style={styles.fullInput}>
              {availableGrades.map(g => <option key={g} value={g}>{g}</option>)}
              {availableGrades.length === 0 && <option value="Grade 8">Grade 8</option>}
            </select>
            
            <button type="submit" style={{ ...styles.btn, backgroundColor: '#15803d', width: '100%' }}>Create Paper Schema</button>
          </form>
        </div>
        <div style={styles.card('#2563eb')}>
          <h4 style={styles.stepTitle('#2563eb')}>Step 2: Active Exam Paper Target</h4>
          <select value={selectedQuizId} onChange={e => setSelectedQuizId(e.target.value)} style={styles.fullInput}>
            <option value="">-- Choose Target Exam Paper --</option>
            {filteredQuizzes.map(q => <option key={q.id} value={q.id}>{q.title} ({q.grade})</option>)}
          </select>
        </div>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1.1fr 1.3fr', gap: '25px', alignItems: 'start' }}>
        <div style={styles.card('#475569')}>
          <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b' }}>➕ Add Custom Question to Bank</h3>
          <form onSubmit={handleSaveQuestion} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <div><label style={styles.label}>ප්‍රශ්න විස්තරය</label><textarea placeholder="ගණිත ගැටලුව මෙතන ලියන්න..." value={qText} onChange={e => setQText(e.target.value)} required style={{ ...styles.fullInput, height: '60px', resize: 'none' }} /></div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'A'} onChange={() => setCorrectOpt('A')} /><input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'B'} onChange={() => setCorrectOpt('B')} /><input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'C'} onChange={() => setCorrectOpt('C')} /><input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'D'} onChange={() => setCorrectOpt('D')} /><input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} required style={styles.fullInput} /></div>
            </div>
            <button type="submit" style={{ ...styles.btn, backgroundColor: '#475569', padding: '11px' }}>Save Inside Repository Bank 💾</button>
          </form>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div style={styles.card('#6b21a8')}>
            <h3 style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#1e293b' }}>📚 Central Question Bank Repository</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '180px', overflowY: 'auto', minHeight:'180px' }}>
              {masterBank.map((q, idx) => (
                <div key={q.id || idx} style={{ backgroundColor: '#f8fafc', padding: '15px', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
                  <h5 style={{ margin: '0 0 10px 0', fontSize: '13.5px' }}>{q.question_text}</h5>
                  <button onClick={() => handleQuickLink(q)} disabled={window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId)} style={{ ...styles.miniBtn, backgroundColor: '#16a34a', color: 'white', border: 'none' }}>➕ Link to Active Paper</button>
                </div>
              ))}
            </div>
          </div>
          <div style={styles.card('#e11d48')}>
            <h3 style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#1e293b' }}>📂 Created Quiz Papers & Visibility Control</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', maxHeight: '220px', overflowY: 'auto' }}>
              {filteredQuizzes.map((qz, idx) => (
                <div key={qz.id || idx} style={{ backgroundColor: '#f8fafc', padding: '12px', borderRadius: '10px', display: 'flex', justifyContent: 'space-between' }}>
                  <span>{qz.title}</span><button onClick={() => handleToggleEnable(qz)} style={{ backgroundColor: isEnabled(qz) ? '#16a34a' : '#dc2626', color: 'white', border: 'none', padding: '4px 10px', borderRadius: '6px' }}>{isEnabled(qz) ? '🟢 Enabled' : '🔴 Disabled'}</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

const styles = {
  card: (color) => ({ backgroundColor: 'white', padding: '24px', borderRadius: '15px', borderTop: `5px solid ${color}`, display: 'flex', flexDirection: 'column' }),
  stepTitle: (color) => ({ margin: '0 0 12px 0', fontSize: '14.5px', color: color, fontWeight: 'bold' }),
  fullInput: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13.5px', boxSizing: 'border-box' },
  btn: { color: 'white', border: 'none', padding: '11px 20px', borderRadius: '8px', fontWeight: 'bold', fontSize: '13.5px' },
  label: { display: 'block', fontSize: '12px', fontWeight: 'bold', color: '#475569', marginBottom: '6px' },
  optRow: { display: 'flex', alignItems: 'center', gap: '10px', width: '100%' },
  miniBtn: { padding: '6px 12px', border: '1px solid #cbd5e1', borderRadius: '6px', fontSize: '11.5px', fontWeight: 'bold' }
};
